func (q *Queries) SearchPlatforms(ctx context.Context, query string) ([]Platform, error) {
	rows, err := q.db.Query(ctx, searchPlatforms, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Platform{}
	for rows.Next() {
		var i Platform
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Name,
			&i.ShortName,
			&i.Manufacturer,
			&i.Kind,
			&i.Family,
			&i.Generation,
			&i.ReleaseYear,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
